install:
set -eu
d=$(mktemp -d)
trap 'rm -rf "$d"' EXIT
base=https://github.com/cli/cli/releases
case "$(uname -m)" in
  x86_64 | amd64) arch=amd64 ;;
  aarch64 | arm64) arch=arm64 ;;
  *) echo "unsupported architecture: $(uname -m)" >&2; exit 1 ;;
esac
url=$(curl -fsSIL -o /dev/null -w '%{url_effective}' "$base/latest")
tag=${url##*/}
case "$tag" in
  v[0-9]*.[0-9]*.[0-9]*) ;;
  *) echo "could not read the latest gh release from $base/latest (got: $url)" >&2; exit 1 ;;
esac
v=${tag#v}
tarball=gh_${v}_linux_${arch}.tar.gz
curl -fsSL "$base/download/$tag/$tarball" -o "$d/gh.tar.gz"
curl -fsSL "$base/download/$tag/gh_${v}_checksums.txt" -o "$d/sums.txt"
sum=$(awk -v f="$tarball" '$2 == f { print $1; exit }' "$d/sums.txt")
case "$sum" in
  *[!0-9a-f]* | "") echo "no sha256 for $tarball in gh_${v}_checksums.txt" >&2; exit 1 ;;
esac
[ "${#sum}" -eq 64 ] || { echo "malformed sha256 for $tarball" >&2; exit 1; }
printf '%s  %s\n' "$sum" "$d/gh.tar.gz" | sha256sum -c -
tar -xzf "$d/gh.tar.gz" -C "$d"
src="$d/gh_${v}_linux_${arch}"
[ -x "$src/bin/gh" ] || { echo "unexpected layout in $tarball" >&2; exit 1; }
mkdir -p {{prefix}}/bin
cp "$src/bin/gh" {{prefix}}/bin/.gh.new
chmod 0755 {{prefix}}/bin/.gh.new
mv -f {{prefix}}/bin/.gh.new {{prefix}}/bin/gh
echo "installed gh $v ($arch) into {{prefix}}/bin"

